async function getSubscriptionFromDb(userId: string): Promise<any | null> {
  const query = 'SELECT * FROM subscriptions WHERE user_id = $1';
  const rows = await db.query(query, [userId]);
  return rows.length > 0 ? rows[0] : null;
}

export async function hasFeatureAccess(userId: string, feature: string): Promise<boolean> {
  const subscription = await getSubscriptionFromDb(userId);
  if (!subscription) return false;

  const validUntil = new Date(subscription.valid_until);
  const features = parseFeatures(subscription.features);
  return validUntil >= new Date() && features.includes(feature);
}
